          case action::action_slot_1:   return "+actionslot 1";
          case action::action_slot_2:   return "+actionslot 2";
          case action::action_slot_3:   return "+actionslot 3";
          case action::action_slot_4:   return "+actionslot 4";
          }

          return "";
        }
      }
    }
  }
}

