		template <typename... Args>
		int invoke_printf(const char* fmt, Args&&... args)
		{
			if (!printf_hook.get_original())
			{
				return std::printf(fmt, std::forward<Args>(args)...);
			}

			return printf_hook.invoke<int>(fmt, std::forward<Args>(args)...);
