		std::string format(va_list* ap, const char* message)
		{
			static thread_local char buffer[0x1000];

			const auto count = vsnprintf_s(buffer, _TRUNCATE, message, *ap);
			if (count < 0)
			{
				return {};
			}

			return { buffer, static_cast<size_t>(count) };
		}

		uint8_t get_attribute(const int type)
		{
			switch (type)
			{
			case con_type_info:
				return 7; // white
			case con_type_warning:
				return 6; // yellow
			case con_type_error:
				return 4; // red
			case con_type_debug:
				return 3; // cyan
			}

			return 7;
		}

		void update()
		{
			std::lock_guard _0(print_mutex);

			show_cursor(false);
			set_cursor_pos(0);
			invoke_printf("%s", con.buffer);
			set_cursor_pos(con.cursor);
			show_cursor(true);
		}

		void clear_output()
		{
			std::lock_guard _0(print_mutex);

			show_cursor(false);
			set_cursor_pos(0);

			for (auto i = 0; i < static_cast<int>(std::strlen(con.buffer)); i++)
			{
				invoke_printf(" ");
			}

			set_cursor_pos(con.cursor);
			show_cursor(true);
		}

		int dispatch_message(const int type, const std::string& message)
		{
			std::lock_guard _0(print_mutex);
			if (!skip_dispatch_log)
			{
				write_log(message);
			}

			game_console::append_output(message);

			clear_output();
			set_cursor_pos(0);

			SetConsoleTextAttribute(OUTPUT_HANDLE, get_attribute(type));
			const auto res = invoke_printf("%s", message.data());
			SetConsoleTextAttribute(OUTPUT_HANDLE, get_attribute(con_type_info));

			if (message.size() <= 0 || message[message.size() - 1] != '\n')
			{
				invoke_printf("\n");
			}

			update();
			return res;
		}

		int dispatch_split_debug_message(const std::string& message)
		{
			std::lock_guard _0(print_mutex);
			if (!skip_dispatch_log)
			{
				write_log("debug:" + message);
			}

			game_console::append_output(message);

			clear_output();
			set_cursor_pos(0);

			SetConsoleTextAttribute(OUTPUT_HANDLE, get_attribute(con_type_error));
			const auto prefix_res = invoke_printf("debug:");
			SetConsoleTextAttribute(OUTPUT_HANDLE, get_attribute(con_type_warning));
			const auto body_res = invoke_printf("%s", message.c_str());
			SetConsoleTextAttribute(OUTPUT_HANDLE, get_attribute(con_type_info));

			if (message.empty() || message.back() != '\n')
			{
				invoke_printf("\n");
			}

			update();
			return prefix_res + body_res;
		}

