	class component final : public component_interface
	{
	public:
		component()
		{
			AllocConsole();
			AttachConsole(GetCurrentProcessId());

			freopen_s((FILE**)stdin, "CONIN$", "r", stdin);
			freopen_s((FILE**)stderr, "CONOUT$", "w", stderr);
			freopen_s((FILE**)stdout, "CONOUT$", "w", stdout);

			ShowWindow(GetConsoleWindow(), SW_HIDE);
		}

		void post_load() override
		{
			// redirect console output to our console
			printf_hook.create(printf, printf_stub);
//#ifndef DEBUG
			com_printf_hook.create(game::game_offset(0x103F6400), com_printf_stub);
//#endif
// 
			// setup external console
			ShowWindow(GetConsoleWindow(), SW_SHOW);

			std::string title = std::string("Project: Consolation [")
				+ build_display_version()
				+ " | "
				+ normalize_build_date(__DATE__)
				+ " "
				+ __TIME__
				+ "] - Console";

			SetConsoleTitleA(title.c_str());

			con.kill_event = CreateEvent(NULL, TRUE, FALSE, NULL);

			con.thread = utils::thread::create_named_thread("Console", []()
			{
				con.thread_id = GetCurrentThreadId();
				MSG msg{};
				PeekMessageA(&msg, nullptr, WM_USER, WM_USER, PM_NOREMOVE);

				const auto handle = GetStdHandle(STD_INPUT_HANDLE);
				HANDLE handles[2] = {handle, con.kill_event};

				INPUT_RECORD record{};
				DWORD num_events{};

				while (!con.kill)
				{
					if (game_window_closed())
					{
						return;
					}

					const auto result = MsgWaitForMultipleObjects(2, handles, FALSE, 100, QS_ALLINPUT);
					if (con.kill || game_window_closed())
					{
						return;
					}

					switch (result)
					{
					case WAIT_OBJECT_0:
					{
						if (!ReadConsoleInput(handle, &record, 1, &num_events) || num_events == 0)
						{
							break;
						}

						handle_input(record);
						break;
					}
					case WAIT_OBJECT_0 + 1:
					{
						return;
					}
					case WAIT_OBJECT_0 + 2:
					{
						while (PeekMessageA(&msg, nullptr, 0, 0, PM_REMOVE))
						{
							if (msg.message == WM_QUIT || msg.message == WM_CLOSE || msg.message == WM_DESTROY)
							{
								game::Cbuf_AddText(0, "quit\n");
								continue;
							}

							TranslateMessage(&msg);
							DispatchMessage(&msg);
						}
						break;
					}
					case WAIT_TIMEOUT:
					default:
						break;
					}
				}
			});
		}

		void pre_destroy() override
		{
			printf_hook.clear();
			com_printf_hook.clear();

			con.kill = true;
			if (con.kill_event)
			{
				SetEvent(con.kill_event);
			}

			if (con.thread_id != 0)
			{
				PostThreadMessageA(con.thread_id, WM_QUIT, 0, 0);
			}

			if (con.thread.joinable())
			{
				CancelSynchronousIo(static_cast<HANDLE>(con.thread.native_handle()));
				con.thread.join();
			}

			ShowWindow(GetConsoleWindow(), SW_HIDE);
			FreeConsole();

			if (con.kill_event)
			{
				CloseHandle(con.kill_event);
				con.kill_event = nullptr;
			}

			con.thread_id = 0;
		}
	};
