				return dvar->current.string[0] != '\0'
					&& strcmp(dvar->current.string, "0") != 0
					&& _stricmp(dvar->current.string, "false") != 0
					&& _stricmp(dvar->current.string, "off") != 0;
			default:
				return dvar->current.integer != 0;
