			}

			if (name_size)
			{
				name[0] = '\0';
			}

			__try
			{
				if (next_out)
				{
					*next_out = current ? current->next : nullptr;
				}

				if (!current || !current->name || !current->name[0])
				{
					return false;
				}

				if (!name_size)
