				}

				name[name_size - 1] = '\0';
				return true;
			}
			__except (EXCEPTION_EXECUTE_HANDLER)
			{
				if (next_out)
				{
					*next_out = nullptr;
				}
				if (name_size)
				{
					name[0] = '\0';
				}
				return false;
			}
		}

