	char* Dvar_ValueToString(game::dvar_s* dvar, game::DvarValue value)
	{
		unsigned int _func = game::game_offset(0x10274F80);
		char* result;
		_asm
		{
			push value;
			mov ecx, dvar;
			call _func;
			add esp, 4;
			mov result, eax;
		}

		return result;
	}

